mapper.select:
select t.audit_id auditId, t.audit_code auditCode, t.audit_type auditType, t.biz_id bizId,
t.current_step currentStep, t.state state, t.submit_staff_id submitStaffId,
t.submit_staff_name submitStaffName, t.submit_time submitTime, t.finish_time finishTime,
t.store_id storeId, t.status_cd statusCd, t.create_time createTime,
c.contract_code bizCode, c.contract_name bizName, c.amount bizAmount, c.party_b bizPartyB,
c.state bizState, td.name bizStateName,
tt.template_name bizTemplateName,
(select count(1) from contract_audit_record r where r.audit_id = t.audit_id and r.status_cd = '0') recordCount
from contract_audit t
left join contract_change_plan p on p.plan_id = t.biz_id and p.status_cd = '0'
left join contract c on c.contract_id = ifnull(p.contract_id, t.biz_id) and c.status_cd = '0'
left join contract_type_template tt on tt.template_id = c.template_id and tt.status_cd = '0'
left join t_dict td on td.status_cd = c.state and td.table_name = 'contract' and td.table_columns = 'state'
where 1 = 1

    and t.audit_id = #{auditId}


    and t.audit_type = #{auditType}


    and t.biz_id = #{bizId}


    and t.biz_id in

        #{item}



    and t.state = #{state}


    and t.state in

        #{item}



    and t.current_step = #{currentStep}


    and t.submit_staff_id = #{submitStaffId}


    and t.store_id = #{storeId}


    and t.audit_code like concat('%', #{auditCodeLike}, '%')


    and (t.audit_code like concat('%', #{searchText}, '%')
    or c.contract_code like concat('%', #{searchText}, '%')
    or c.contract_name like concat('%', #{searchText}, '%'))


    and exists (select 1 from contract_audit_record r
    where r.audit_id = t.audit_id and r.auditor_id = #{auditorId}

        and r.result = #{result}
        and r.step = t.current_step

    )


    and t.status_cd = #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

select count(1) count
from contract_audit t
left join contract c on c.contract_id = t.biz_id and c.status_cd = '0'
where 1 = 1

    and t.audit_type = #{auditType}


    and t.biz_id = #{bizId}


    and t.state = #{state}


    and t.state in

        #{item}



    and t.submit_staff_id = #{submitStaffId}


    and t.store_id = #{storeId}


    and t.audit_code like concat('%', #{auditCodeLike}, '%')


    and (t.audit_code like concat('%', #{searchText}, '%')
    or c.contract_code like concat('%', #{searchText}, '%')
    or c.contract_name like concat('%', #{searchText}, '%'))


    and exists (select 1 from contract_audit_record r
    where r.audit_id = t.audit_id and r.auditor_id = #{auditorId}

        and r.result = #{result}
        and r.step = t.current_step

    )


    and t.status_cd = #{statusCd}

select
(select count(1) from contract_audit a
join contract_audit_record r on r.audit_id = a.audit_id and r.step = a.current_step
where a.state = '0' and a.status_cd = '0' and r.status_cd = '0' and r.result = '0'

    and a.store_id = #{storeId}


    and r.auditor_id = #{staffId}

) pending,
(select count(1) from contract_audit_record r
join contract_audit a on a.audit_id = r.audit_id
where r.result = '1' and r.status_cd = '0'
and date_format(r.audit_time, '%Y%m') = date_format(now(), '%Y%m')

    and a.store_id = #{storeId}


    and r.auditor_id = #{staffId}

) monthPass,
(select count(1) from contract_audit_record r
join contract_audit a on a.audit_id = r.audit_id
where r.result = '2' and r.status_cd = '0'
and date_format(r.audit_time, '%Y%m') = date_format(now(), '%Y%m')

    and a.store_id = #{storeId}


    and r.auditor_id = #{staffId}

) monthReject
